// Package web serves the React frontend embedded in the backend binary
// (embed.FS), so that the Podman Quadlet deployment is a single artifact: no
// separate static container/server is needed.
//
// The actual contents of dist/ are generated by `npm run build` in frontend/
// and copied here by `make build` (see Makefile), overwriting the on-disk
// directory entirely. That is why dist/ only tracks a .gitkeep: the frontend
// build is never committed, and `go build` without a prior frontend build
// serves the placeholder embedded below instead of failing.
package web

import (
	"bytes"
	"embed"
	"io/fs"
	"net/http"
	"path"
	"strings"
	"time"
)

//go:embed all:dist
var distFS embed.FS

const placeholderHTML = `<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><title>Bayplan</title></head>
<body><p>Frontend not built: run <code>make build</code> (or
<code>npm run build</code> in frontend/) to generate the SPA.</p></body></html>`

// Handler serves the frontend's static assets with a fallback to index.html
// for client-side routes (SPA with react-router in history mode).
//
// Directories are never listed (http.FileServer would print the contents of
// /assets/): a directory path is a client route like any other. Caching: the
// files under assets/ carry a content hash in their name (Vite), so they are
// immutable; index.html must always be revalidated, or a browser keeps
// loading the chunks of the previous version after an upgrade.
func Handler() (http.Handler, error) {
	sub, err := fs.Sub(distFS, "dist")
	if err != nil {
		return nil, err
	}
	index, err := fs.ReadFile(sub, "index.html")
	if err != nil {
		// Frontend build not present (only the embedded .gitkeep).
		index = nil
	}
	fileServer := http.FileServer(http.FS(sub))

	serveIndex := func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		if index == nil {
			_, _ = w.Write([]byte(placeholderHTML))
			return
		}
		http.ServeContent(w, r, "index.html", time.Time{}, bytes.NewReader(index))
	}

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		name := trimLeadingSlash(path.Clean(r.URL.Path))
		if name == "" || name == "." || name == "index.html" {
			serveIndex(w, r)
			return
		}
		st, err := fs.Stat(sub, name)
		if err != nil || st.IsDir() {
			if strings.HasPrefix(name, "assets/") || name == "assets" {
				// A missing chunk must be a 404, not index.html served as
				// JavaScript (which the browser rejects with a MIME error).
				http.NotFound(w, r)
				return
			}
			// Not a known file: delegate to index.html so that react-router
			// resolves the route on the client.
			serveIndex(w, r)
			return
		}
		if strings.HasPrefix(name, "assets/") {
			w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
		}
		fileServer.ServeHTTP(w, r)
	}), nil
}

func trimLeadingSlash(p string) string {
	if len(p) > 0 && p[0] == '/' {
		return p[1:]
	}
	return p
}
